import { Button, Card, EmptyState, Spinner } from '@socialscore/ui';
import { useCallback } from 'react';
import type { ReactElement } from 'react';

import { ErrorNote } from '../components/ErrorNote.js';
import { FieldRow } from '../components/FieldRow.js';
import { useApi, useT } from '../hooks/usePlugin.js';
import { useResource } from '../hooks/useResource.js';
import { humanize } from '../lib/format.js';
import type { ProfileRef } from '../lib/format.js';
import { isProfileField } from '../lib/profile.js';
import type { Profile, ProfileCategories } from '../types/index.js';

const CATEGORY_ORDER = [
  'identity',
  'contact',
  'digitalFootprint',
  'interests',
  'professional',
  'b2b',
  'healthSignals',
  'segments',
  'ownData',
] as const;

type Row = { key: string; label: string; field: Parameters<typeof FieldRow>[0]['field'] };

/** Flattens a category's fields. Lists of fields and the nested lists of 7.1 (platforms, interests, segments) become rows. */
function rowsOf(fields: Record<string, unknown>): Row[] {
  const rows: Row[] = [];
  Object.entries(fields).forEach(([name, value]) => {
    const items = Array.isArray(value) ? value : [value];
    items.forEach((item, index) => {
      if (isProfileField(item)) {
        rows.push({ key: `${name}-${index}`, label: humanize(name), field: item });
        return;
      }
      if (typeof item !== 'object' || item === null) return;
      const record = item as Record<string, unknown>;
      const title = [record.platform, record.category, record.segmentLabel, record.title].find(
        (v) => typeof v === 'string'
      ) as string | undefined;
      Object.entries(record).forEach(([inner, nested]) => {
        if (isProfileField(nested)) {
          rows.push({
            key: `${name}-${index}-${inner}`,
            label: title ?? humanize(inner),
            field: nested,
          });
        }
      });
    });
  });
  return rows;
}

export interface ProfileViewProps extends ProfileRef {
  onBack?: () => void;
}

/** The 7.1 profile of one customer or order, category by category. A category with no data is not shown (7.2). */
export function ProfileView({ kind, externalId, onBack }: ProfileViewProps): ReactElement {
  const api = useApi();
  const t = useT();
  const load = useCallback(
    () => (kind === 'order' ? api.getOrderProfile(externalId) : api.getCustomerProfile(externalId)),
    [api, kind, externalId]
  );
  const { data, error, loading, reload } = useResource<Profile>(load);

  const categories = (data?.categories ?? {}) as ProfileCategories;
  const shown = CATEGORY_ORDER.map((name) => {
    const category = categories[name];
    const rows =
      category && category.status === 'available'
        ? rowsOf(category.fields as Record<string, unknown>)
        : [];
    return { name, rows };
  }).filter((entry) => entry.rows.length > 0);

  return (
    <div className="ss-pc-profile">
      <div className="ss-pc-profile-head">
        {onBack && (
          <Button variant="link" onClick={onBack}>
            {t('common.back')}
          </Button>
        )}
        <h2 className="ss-pc-heading">{t('profile.title')}</h2>
      </div>
      {loading && !data && <Spinner label={t('profile.loading')} />}
      {error !== undefined && <ErrorNote error={error} onRetry={reload} />}
      {data && shown.length === 0 && <EmptyState title={t('profile.empty')} />}
      {shown.map(({ name, rows }) => (
        <Card key={name} title={t(`profile.category.${name}`)} headingLevel={3}>
          <dl className="ss-pc-fields">
            {rows.map((row) => (
              <FieldRow key={row.key} label={row.label} field={row.field} />
            ))}
          </dl>
        </Card>
      ))}
    </div>
  );
}
