import { Badge } from '@socialscore/ui';
import type { ReactElement } from 'react';

import { useT } from '../hooks/usePlugin.js';
import type { CheckLabel } from '../types/index.js';

export function CheckLabels({ labels }: { labels: CheckLabel[] }): ReactElement | null {
  const t = useT();
  if (labels.length === 0) return null;
  return (
    <ul className="ss-pc-labels">
      {labels.map((label) => (
        <li key={label}>
          <Badge variant={label === 'review_before_shipping' ? 'warning' : 'neutral'}>
            {t(`label.${label}`)}
          </Badge>
        </li>
      ))}
    </ul>
  );
}
