import { ApiError } from '../api/errors.js';

import { useT } from './usePlugin.js';

export function useErrorText(): (error: unknown) => string {
  const t = useT();
  return (error) => {
    if (error instanceof ApiError) {
      if (error.status === 402 || error.code === 'plan_required') return t('error.planRequired');
      if (error.status === 429) {
        return error.retryAfter !== undefined
          ? t('error.rateLimited', { seconds: error.retryAfter })
          : t('error.rateLimitedNoWait');
      }
      if (error.status === 401) return t('error.unauthorized');
    }
    return t('error.generic');
  };
}
