import { Button, Card, Spinner } from '@socialscore/ui';
import { useRef, useState } from 'react';
import type { ReactElement } from 'react';

import { newIdempotencyKey } from '../api/client.js';
import { CheckLabels } from '../components/CheckLabels.js';
import { CheckSignals } from '../components/CheckSignals.js';
import { ErrorNote } from '../components/ErrorNote.js';
import { useApi, useHost, useT } from '../hooks/usePlugin.js';
import { profilePath } from '../lib/format.js';
import type { ProfileRef } from '../lib/format.js';
import type { CheckResult } from '../types/index.js';

export type CheckPanelProps = ProfileRef;

function CheckPanelFor({ kind, externalId }: CheckPanelProps): ReactElement {
  const api = useApi();
  const host = useHost();
  const t = useT();
  const [running, setRunning] = useState(false);
  const [result, setResult] = useState<CheckResult>();
  const [error, setError] = useState<unknown>();
  // One key per click, reused if the same click is retried after a failure, so a retry is never charged twice.
  const key = useRef<string | undefined>(undefined);

  const run = async () => {
    setRunning(true);
    setError(undefined);
    key.current ??= newIdempotencyKey();
    try {
      const subject =
        kind === 'order' ? { orderExternalId: externalId } : { customerExternalId: externalId };
      setResult(await api.runCheck(subject, key.current));
      key.current = undefined;
    } catch (e) {
      setError(e);
    } finally {
      setRunning(false);
    }
  };

  return (
    <Card title={t('check.title')} headingLevel={3} hideWhenEmpty={false}>
      <div className="ss-pc-panel">
        {result && (
          <>
            <CheckLabels labels={result.labels} />
            <CheckSignals profile={result.profile} />
          </>
        )}
        {error !== undefined && <ErrorNote error={error} />}
        {running && <Spinner label={t('check.checking')} />}
        <div className="ss-pc-actions">
          <Button variant="contained-primary" disabled={running} onClick={run}>
            {t('check.button')}
          </Button>
          {result && (
            <Button variant="link" onClick={() => host.navigate(profilePath({ kind, externalId }))}>
              {t('check.seeFullProfile')}
            </Button>
          )}
        </div>
      </div>
    </Card>
  );
}

/** Compact panel for one order or customer screen of the store admin (BRD 12.3). */
export function CheckPanel(props: CheckPanelProps): ReactElement {
  // Keyed by subject: moving to another order or customer starts from a clean panel (no old result, labels or Idempotency-Key).
  return <CheckPanelFor key={`${props.kind}:${props.externalId}`} {...props} />;
}
