import { LevelIndicator } from '@socialscore/ui';
import type { ReactElement } from 'react';

import { useT } from '../hooks/usePlugin.js';
import type { Profile, ProfileField } from '../types/index.js';

interface ScoreRow {
  key: string;
  label: string;
  field?: ProfileField<number>;
  inverted?: boolean;
}

/** The health signals of BRD 12.3 for one profile. Masked or missing values say so. */
export function CheckSignals({ profile }: { profile: Profile }): ReactElement | null {
  const t = useT();
  const health = profile.categories.healthSignals?.fields;
  const b2b = profile.categories.b2b?.fields.isBusinessEmail;

  // Digital presence is the Social Score of 7.1 health signals (assumption, see docs/plugin-core.md).
  const scores: ScoreRow[] = [
    { key: 'presence', label: t('check.digitalPresence'), field: health?.socialScore },
    { key: 'email', label: t('check.emailQuality'), field: health?.emailScore },
    { key: 'phone', label: t('check.phoneQuality'), field: health?.phoneScore },
    { key: 'fraud', label: t('check.fraudScore'), field: health?.fraudScore, inverted: true },
  ];
  const shown = scores.filter((row) => row.field);
  if (shown.length === 0 && !b2b) return <p className="ss-pc-muted">{t('check.noSignals')}</p>;

  return (
    <ul className="ss-pc-signals">
      {shown.map(({ key, label, field, inverted }) => (
        <li key={key} className="ss-pc-signal">
          {field?.value === undefined ? (
            <>
              <span className="ss-pc-signal-label">{label}</span>
              <span className="ss-pc-muted">
                {field?.masked ? t('profile.masked') : t('profile.noValue')}
              </span>
            </>
          ) : (
            <LevelIndicator
              label={label}
              value={field.value}
              inverted={inverted}
              showLevelName
              valueLabel={<span className="ss-pc-signal-value">{Math.round(field.value)}</span>}
            />
          )}
        </li>
      ))}
      {b2b && (
        <li className="ss-pc-signal">
          <span className="ss-pc-signal-label">{t('check.businessBuyer')}</span>
          <span>
            {b2b.value === undefined
              ? b2b.masked
                ? t('profile.masked')
                : t('profile.noValue')
              : b2b.value
                ? t('check.businessBuyerYes')
                : t('check.businessBuyerNo')}
          </span>
        </li>
      )}
    </ul>
  );
}
