import { useCallback, useContext } from 'react';

import type { ApiClient } from '../api/client.js';
import { PluginContext } from '../context.js';
import type { PluginContextValue } from '../context.js';
import type { PluginHost } from '../host.js';
import { messages } from '../messages.js';
import type { MessageKey } from '../messages.js';

export type TFunction = (key: MessageKey, vars?: Record<string, string | number>) => string;

export function usePlugin(): PluginContextValue {
  const ctx = useContext(PluginContext);
  if (!ctx) throw new Error('Plugin screens must be rendered inside <PluginProvider>');
  return ctx;
}

export const useApi = (): ApiClient => usePlugin().api;
export const useHost = (): PluginHost => usePlugin().host;

function interpolate(template: string, vars?: Record<string, string | number>): string {
  if (!vars) return template;
  return template.replace(/\{(\w+)\}/g, (match, name: string) =>
    name in vars ? String(vars[name]) : match
  );
}

/** Host translation first; the English text when the host has none (or returns the key). */
export function useT(): TFunction {
  const { host } = usePlugin();
  return useCallback(
    (key, vars) => {
      const translated = host.t?.(key, vars);
      if (translated && translated !== key) return translated;
      return interpolate(messages[key], vars);
    },
    [host]
  );
}
