import { Badge } from '@socialscore/ui';
import type { ReactElement } from 'react';

import { useT } from '../hooks/usePlugin.js';
import { formatDate, humanize } from '../lib/format.js';
import type { ProfileField } from '../types/index.js';

function valueText(value: unknown, yes: string, no: string): string {
  if (typeof value === 'boolean') return value ? yes : no;
  if (typeof value === 'object') return JSON.stringify(value);
  return String(value);
}

export interface FieldRowProps {
  label: string;
  field: ProfileField;
}

/** One 7.1 field: the value as returned (masked stays masked), its level, source and reason. */
export function FieldRow({ label, field }: FieldRowProps): ReactElement {
  const t = useT();
  const level = field.confidenceLevel;
  const meta = [
    field.sourceDetail
      ? `${humanize(field.source)}: ${field.sourceDetail}`
      : t('profile.source', { source: humanize(field.source) }),
    field.reason ? t('profile.reason', { reason: field.reason }) : '',
    field.collectedAt ? t('profile.collectedAt', { date: formatDate(field.collectedAt) }) : '',
  ].filter(Boolean);

  return (
    <div className="ss-pc-field">
      <dt className="ss-pc-field-label">{label}</dt>
      <dd className="ss-pc-field-body">
        <span className="ss-pc-field-value">
          {field.masked
            ? t('profile.masked')
            : field.value === undefined
              ? t('profile.noValue')
              : valueText(field.value, t('common.yes'), t('common.no'))}
        </span>
        {level && (
          <Badge
            variant={level}
            aria-label={t('profile.confidence', { level: t(`level.${level}`) })}
          >
            {t(`level.${level}`)}
          </Badge>
        )}
        {meta.length > 0 && <span className="ss-pc-field-meta">{meta.join(' · ')}</span>}
      </dd>
    </div>
  );
}
