import { useMemo } from 'react';
import type { ReactElement, ReactNode } from 'react';

import { ApiClient } from './api/client.js';
import { PluginContext } from './context.js';
import type { PluginHost } from './host.js';

export interface PluginProviderProps {
  host: PluginHost;
  /** SocialScore's id for the connected store (from the connect flow). */
  storeId: string | number;
  children: ReactNode;
}

/** Wrap the screens once; they read the host and the API client from here. */
export function PluginProvider({ host, storeId, children }: PluginProviderProps): ReactElement {
  const id = String(storeId);
  const value = useMemo(() => ({ host, storeId: id, api: new ApiClient(host, id) }), [host, id]);
  return <PluginContext.Provider value={value}>{children}</PluginContext.Provider>;
}
