const camel = (key: string) => key.replace(/_([a-z0-9])/g, (_, c: string) => c.toUpperCase());
const snake = (key: string) => key.replace(/[A-Z]/g, (c) => `_${c.toLowerCase()}`);

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/** snake_case keys to camelCase and null values removed, the way the SocialScore client reads the API. */
export function fromWire<T>(value: unknown): T {
  if (Array.isArray(value)) return value.map((item) => fromWire(item)) as T;
  if (!isPlainObject(value)) return value as T;
  const out: Record<string, unknown> = {};
  Object.entries(value).forEach(([key, item]) => {
    if (item !== null) out[camel(key)] = fromWire(item);
  });
  return out as T;
}

/** camelCase keys to snake_case for request bodies; undefined values are dropped by JSON.stringify. */
export function toWire(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(toWire);
  if (!isPlainObject(value)) return value;
  const out: Record<string, unknown> = {};
  Object.entries(value).forEach(([key, item]) => {
    out[snake(key)] = toWire(item);
  });
  return out;
}
