import {
  Badge,
  Button,
  Card,
  EmptyState,
  Spinner,
  Tab,
  TabList,
  TabPanel,
  Table,
  Tabs,
} from '@socialscore/ui';
import type { TableColumn } from '@socialscore/ui';
import { useCallback, useState } from 'react';
import type { ReactElement } from 'react';

import { ErrorNote } from '../components/ErrorNote.js';
import { useApi, useT } from '../hooks/usePlugin.js';
import { useResource } from '../hooks/useResource.js';
import { formatDate, formatMoney } from '../lib/format.js';
import type { ProfileRef } from '../lib/format.js';
import type { CheckedCustomer, RiskyOrder, SegmentSummary } from '../types/index.js';

import { ProfileView } from './ProfileView.js';
import { SettingsScreen } from './SettingsScreen.js';

export type DashboardTab = 'overview' | 'profiles' | 'segments' | 'settings';

const TABS: DashboardTab[] = ['overview', 'profiles', 'segments', 'settings'];

interface TabProps {
  openProfile: (ref: ProfileRef) => void;
}

function OverviewTab({ openProfile }: TabProps): ReactElement {
  const api = useApi();
  const t = useT();
  const load = useCallback(() => api.getOverview(), [api]);
  const { data, error, loading, reload } = useResource(load);

  if (error !== undefined) return <ErrorNote error={error} onRetry={reload} />;
  if (!data) return loading ? <Spinner label={t('common.loading')} /> : <div />;

  const columns: TableColumn<RiskyOrder>[] = [
    {
      key: 'externalId',
      header: t('overview.column.order'),
      render: (row) => (
        <Button
          variant="link"
          aria-label={t('overview.viewOrder', { id: row.externalId })}
          onClick={() => openProfile({ kind: 'order', externalId: row.externalId })}
        >
          {row.externalId}
        </Button>
      ),
    },
    {
      key: 'placedAt',
      header: t('overview.column.placed'),
      render: (row) => formatDate(row.placedAt),
    },
    {
      key: 'total',
      header: t('overview.column.total'),
      align: 'end',
      render: (row) => formatMoney(row.total, row.currency),
    },
    { key: 'fraudScore', header: t('overview.column.fraud'), align: 'end' },
  ];

  return (
    <div className="ss-pc-overview">
      <div className="ss-pc-stats">
        <Card title={t('overview.checkedCustomers')} headingLevel={3}>
          <p className="ss-pc-stat">{data.checkedCustomers}</p>
        </Card>
        <Card title={t('overview.checkedOrders')} headingLevel={3}>
          <p className="ss-pc-stat">{data.checkedOrders}</p>
        </Card>
        <Card
          title={t('overview.businessBuyers')}
          headingLevel={3}
          when={data.businessBuyers !== undefined}
        >
          <p className="ss-pc-stat">{data.businessBuyers}</p>
        </Card>
      </div>
      <Card title={t('overview.riskyOrders')} headingLevel={3} hideWhenEmpty={false}>
        <Table
          caption={t('overview.riskyOrdersCaption')}
          columns={columns}
          rows={data.riskyOrders}
          getRowKey={(row) => row.externalId}
          empty={t('overview.riskyOrdersEmpty')}
        />
      </Card>
    </div>
  );
}

const PAGE_SIZE = 20;

function ProfilesTab({ openProfile }: TabProps): ReactElement {
  const api = useApi();
  const t = useT();
  const [page, setPage] = useState(1);
  const load = useCallback(() => api.listCheckedCustomers(page, PAGE_SIZE), [api, page]);
  const { data, error, loading, reload } = useResource(load);

  if (error !== undefined) return <ErrorNote error={error} onRetry={reload} />;
  if (!data) return loading ? <Spinner label={t('common.loading')} /> : <div />;

  const columns: TableColumn<CheckedCustomer>[] = [
    {
      key: 'displayName',
      header: t('profiles.column.customer'),
      render: (row) => {
        const name = row.displayName ?? row.externalId;
        return (
          <Button
            variant="link"
            aria-label={t('profiles.open', { name })}
            onClick={() => openProfile({ kind: 'customer', externalId: row.externalId })}
          >
            {name}
          </Button>
        );
      },
    },
    { key: 'email', header: t('profiles.column.email') },
    { key: 'ordersCount', header: t('profiles.column.orders'), align: 'end' },
    {
      key: 'healthLevel',
      header: t('profiles.column.health'),
      render: (row) =>
        row.healthLevel ? (
          <Badge variant={row.healthLevel}>{t(`level.${row.healthLevel}`)}</Badge>
        ) : null,
    },
    {
      key: 'checkedAt',
      header: t('profiles.column.checked'),
      render: (row) => formatDate(row.checkedAt),
    },
  ];

  return (
    <Table
      caption={t('profiles.caption')}
      columns={columns}
      rows={data.items}
      getRowKey={(row) => row.externalId}
      pageSize={PAGE_SIZE}
      page={page}
      onPageChange={setPage}
      totalRecords={data.total}
      empty={<EmptyState title={t('profiles.empty')} />}
    />
  );
}

function SegmentsTab(): ReactElement {
  const api = useApi();
  const t = useT();
  const load = useCallback(() => api.listSegments(), [api]);
  const { data, error, loading, reload } = useResource(load);

  if (error !== undefined) return <ErrorNote error={error} onRetry={reload} />;
  if (!data) return loading ? <Spinner label={t('common.loading')} /> : <div />;

  const columns: TableColumn<SegmentSummary>[] = [
    { key: 'label', header: t('segments.column.name') },
    {
      key: 'status',
      header: t('segments.column.status'),
      render: (row) => (row.status ? t(`segments.status.${row.status}`) : ''),
    },
    { key: 'size', header: t('segments.column.size'), align: 'end' },
  ];

  return (
    <div>
      <p className="ss-pc-text">{t('segments.editInSocialScore')}</p>
      <Table
        caption={t('segments.caption')}
        columns={columns}
        rows={data}
        getRowKey={(row) => row.id}
        empty={<EmptyState title={t('segments.empty')} />}
      />
    </div>
  );
}

export interface StoreDashboardProps {
  /** Opens on a profile, for example when the adapter routed "See full profile" here. */
  initialProfile?: ProfileRef;
  initialTab?: DashboardTab;
}

/** The store dashboard (BRD 12.2): Overview, Profiles, Segments and Settings, no iframe. */
export function StoreDashboard({
  initialProfile,
  initialTab = 'overview',
}: StoreDashboardProps): ReactElement {
  const t = useT();
  const [tab, setTab] = useState<string>(initialTab);
  const [profile, setProfile] = useState<ProfileRef | undefined>(initialProfile);

  if (profile) {
    return (
      <ProfileView
        kind={profile.kind}
        externalId={profile.externalId}
        onBack={() => setProfile(undefined)}
      />
    );
  }

  return (
    <div className="ss-pc-dashboard">
      <h1 className="ss-pc-heading">{t('dashboard.title')}</h1>
      <Tabs value={tab} onValueChange={setTab}>
        <TabList aria-label={t('dashboard.tabs')}>
          {TABS.map((name) => (
            <Tab key={name} value={name}>
              {t(`dashboard.tab.${name}`)}
            </Tab>
          ))}
        </TabList>
        <TabPanel value="overview">
          <OverviewTab openProfile={setProfile} />
        </TabPanel>
        <TabPanel value="profiles">
          <ProfilesTab openProfile={setProfile} />
        </TabPanel>
        <TabPanel value="segments">
          <SegmentsTab />
        </TabPanel>
        <TabPanel value="settings">
          <SettingsScreen />
        </TabPanel>
      </Tabs>
    </div>
  );
}
